// Offline checks for the Google Cloud icon pack (`gcp`), generated by scripts/build-gcp-icon-pack.mjs.
// The pack is not part of the public copy of this repository, so these checks are skipped when
// `<packs dir>/gcp.json` does not exist, unless REQUIRE_GCP_PACK=1 (CI of an edition that commits the pack), in
// which case a missing pack fails.
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const { PACKS_DIR, loadPacks } = require('../utils/icons');

const PACK_FILE = path.join(PACKS_DIR, 'gcp.json');
if (!fs.existsSync(PACK_FILE)) {
  if (process.env.REQUIRE_GCP_PACK === '1') {
    console.error(`FAIL  Google Cloud pack required (REQUIRE_GCP_PACK=1) but ${PACK_FILE} does not exist`);
    process.exit(1);
  }
  console.log(`SKIP  Google Cloud pack tests: ${PACK_FILE} does not exist (set REQUIRE_GCP_PACK=1 to require it)`);
  process.exit(0);
}

let failures = 0;
function check(name, fn) {
  try { fn(); console.log(`PASS  ${name}`); } catch (e) { failures++; console.error(`FAIL  ${name}: ${e.message}`); }
}

const CLONIX = 'Clonix Secure Diagram Studio';
const api = loadPacks(PACKS_DIR, CLONIX);
const gcp = api.ICON_PACKS.find((p) => p.prefix === 'gcp');

check('gcp pack is present and self-consistent', () => {
  assert.ok(gcp, 'gcp pack missing');
  assert.strictEqual(gcp.width, 512);
  assert.strictEqual(gcp.height, 512);
  assert.strictEqual(gcp.info.total, Object.keys(gcp.icons).length, 'info.total drifted from icon count');
  for (const id of ['cloud-run', 'bigquery', 'gke', 'cloud-storage', 'networking', 'security-identity']) {
    assert.ok(gcp.icons[id], `missing base icon ${id}`);
  }
});

check('every alias points at an existing base icon and names are well-formed', () => {
  const valid = /^[a-z0-9]+(-[a-z0-9]+)*$/;
  for (const id of Object.keys(gcp.icons)) assert.ok(valid.test(id), `bad icon id ${id}`);
  for (const [alias, { parent }] of Object.entries(gcp.aliases)) {
    assert.ok(valid.test(alias), `bad alias ${alias}`);
    assert.ok(gcp.icons[parent], `alias ${alias} → missing parent ${parent}`);
    assert.ok(!gcp.icons[alias], `alias ${alias} shadows a base icon`);
  }
  for (const a of ['vpc', 'gcs', 'iam', 'scc', 'chronicle', 'pubsub', 'cloud-functions', 'kms']) {
    assert.ok(gcp.aliases[a], `expected alias ${a}`);
  }
});

check('icon bodies contain only inert vector markup (no script/style/ids/external refs)', () => {
  // Stricter than the general pack rules: Google's artwork is normalised to plain shapes.
  const forbidden = [/<script/i, /<style/i, /<foreignObject/i, /<image/i, /<use\b/i, /\shref=/i, /xlink:href/i,
    /url\(#/i, /\sclass=/i, /\sid=/i, /javascript:/i, /\son[a-z]+=/i, /<a\b/i];
  for (const [id, { body }] of Object.entries(gcp.icons)) {
    assert.ok(body.startsWith('<') && body.length > 50, `${id}: suspicious body`);
    for (const re of forbidden) assert.ok(!re.test(body), `${id}: body matches ${re}`);
    assert.strictEqual((body.match(/<g\b/g) || []).length, (body.match(/<\/g>/g) || []).length, `${id}: unbalanced <g>`);
  }
});

check('the pack carries its label, owner, terms and notices', () => {
  assert.strictEqual(gcp.sirenia.format, 1);
  assert.strictEqual(gcp.sirenia.label, 'Google Cloud');
  assert.strictEqual(gcp.sirenia.owner, 'Google');
  assert.strictEqual(gcp.sirenia.termsUrl, 'https://about.google/brand-resource-center/');
  for (const k of ['editor', 'export']) assert.ok(/trademarks of Google LLC/.test(gcp.sirenia.notice[k]), `notice.${k}`);
  assert.ok(!api.ICON_PACKS_SCRIPT.includes('sirenia'), 'the render page gets the Iconify part only');
});

check('findUnknownIcons resolves Google Cloud names and aliases, flags wrong case', () => {
  assert.deepStrictEqual(api.findUnknownIcons('service a(gcp:cloud-run)[Run]\nb@{ icon: "gcp:vpc" }'), []);
  assert.deepStrictEqual(api.findUnknownIcons('service a(gcp:does-not-exist)[X]\nservice b(gcp:Cloud-Run)[Y]'), ['gcp:does-not-exist', 'gcp:Cloud-Run']);
  api.packsUsedBy('architecture-beta\n  group vpc(gcp:vpc)[VPC]\n  service run(gcp:cloud-run)[Run] in vpc');
  assert.deepStrictEqual(api.findUnknownIcons('architecture-beta\n  service a(gcp:Cloud-Run)[x]'), ['gcp:Cloud-Run']);
  assert.ok(api.KNOWN_ICONS.get('gcp').size > 400, 'expected icons + aliases to be registered');
});

check('the export notice for the Clonix edition is exactly the published string', () => {
  const notice = api.attributionNotice(api.packsUsedBy('architecture-beta\n  service a(gcp:cloud-run)[Cloud Run]'));
  assert.strictEqual(
    notice,
    'Google Cloud and the Google Cloud product icons are trademarks of Google LLC, used unmodified solely to ' +
      'depict Google Cloud products in this architecture diagram. Generated with Clonix Secure Diagram Studio, ' +
      'an independent product not affiliated with, sponsored by, or endorsed by Google.'
  );
  assert.ok(notice.length < 500);
  assert.strictEqual(api.attributionNotice(api.packsUsedBy('graph TD; A-->B')), null);
});

check('the export notice names the default product', () => {
  const notice = loadPacks(PACKS_DIR, 'Sirenia').attributionNotice(['gcp']);
  assert.ok(notice.includes('Generated with Sirenia, an independent product not affiliated with, sponsored by, or endorsed by Google.'));
});

if (failures) {
  console.error(`\n${failures} test(s) failed`);
  process.exit(1);
}
console.log('\nAll Google Cloud pack tests passed');
